import AppKit

/// Crow's icon artwork, bundled from apps/macos/Resources by scripts/run-crow-mac.sh
/// (generated by scripts/make-app-icon.py). Running the bare binary outside the
/// app bundle has none of it, so every use has a fallback.
enum CrowBrand {
    /// The app icon; the system's generic icon outside the bundle.
    static var appIcon: NSImage { NSApp.applicationIconImage ?? NSImage() }

    /// 18 pt template silhouette for the menu bar; macOS tints it.
    static let menuBarGlyph: NSImage? = {
        guard let image = Bundle.main.image(forResource: "MenuBarGlyph") else { return nil }
        image.size = NSSize(width: 18, height: 18)
        image.isTemplate = true
        return image
    }()

    private static let islandGlyph: NSImage? = Bundle.main.image(forResource: "IslandGlyph")
    @MainActor private static var tinted: [CGFloat: NSImage] = [:]

    /// The silhouette in white at the given opacity, cached because the island
    /// redraws it every frame.
    @MainActor
    static func islandGlyph(alpha: CGFloat) -> NSImage? {
        let key = (alpha * 100).rounded() / 100
        if let image = tinted[key] { return image }
        guard let glyph = islandGlyph else { return nil }
        let image = NSImage(size: glyph.size, flipped: false) { rect in
            glyph.draw(in: rect)
            NSColor.white.withAlphaComponent(key).set()
            rect.fill(using: .sourceAtop)
            return true
        }
        tinted[key] = image
        return image
    }
}
